com.mirth.connect.plugins.javascriptstep.script:
function hl7Value(node) {
    return String(node.toString()).replace(
        /^\s+|\s+$/g,
        ''
    );
}

function required(value, fieldName) {
    var normalized = String(value).replace(
        /^\s+|\s+$/g,
        ''
    );

    if (!normalized) {
        throw new Error(
            'Missing mandatory HL7 field: ' + fieldName
        );
    }

    return normalized;
}

function fhirDate(hl7Date) {
    if (!hl7Date || hl7Date.length < 8) {
        return null;
    }

    return hl7Date.substring(0, 4) + '-' +
        hl7Date.substring(4, 6) + '-' +
        hl7Date.substring(6, 8);
}

function fhirDateTime(hl7DateTime) {
    if (!hl7DateTime || hl7DateTime.length < 8) {
        return null;
    }

    var result =
        hl7DateTime.substring(0, 4) + '-' +
        hl7DateTime.substring(4, 6) + '-' +
        hl7DateTime.substring(6, 8);

    if (hl7DateTime.length >= 14) {
        result += 'T' +
            hl7DateTime.substring(8, 10) + ':' +
            hl7DateTime.substring(10, 12) + ':' +
            hl7DateTime.substring(12, 14) + '-03:00';
    }

    return result;
}

function mapGender(hl7Sex) {
    var normalized = String(hl7Sex).toUpperCase();

    if (normalized === 'M') {
        return 'male';
    }

    if (normalized === 'F') {
        return 'female';
    }

    if (normalized === 'O') {
        return 'other';
    }

    return 'unknown';
}

function mapResultStatus(hl7Status) {
    var normalized = String(hl7Status).toUpperCase();

    if (normalized === 'F') {
        return 'final';
    }

    if (normalized === 'C') {
        return 'corrected';
    }

    if (normalized === 'P') {
        return 'preliminary';
    }

    return 'unknown';
}

var controlId = required(
    hl7Value(msg['MSH']['MSH.10']['MSH.10.1']),
    'MSH-10'
);

var patientId = required(
    hl7Value(msg['PID']['PID.3']['PID.3.1']),
    'PID-3.1'
);

var lastName = required(
    hl7Value(msg['PID']['PID.5']['PID.5.1']),
    'PID-5.1'
);

var firstName = required(
    hl7Value(msg['PID']['PID.5']['PID.5.2']),
    'PID-5.2'
);

var birthDate = hl7Value(
    msg['PID']['PID.7']['PID.7.1']
);

var sex = hl7Value(
    msg['PID']['PID.8']['PID.8.1']
);

var orderId = required(
    hl7Value(msg['ORC']['ORC.2']['ORC.2.1']),
    'ORC-2.1'
);

var accessionId = required(
    hl7Value(msg['OBR']['OBR.3']['OBR.3.1']),
    'OBR-3.1'
);

var panelCode = required(
    hl7Value(msg['OBR']['OBR.4']['OBR.4.1']),
    'OBR-4.1'
);

var panelDescription = hl7Value(
    msg['OBR']['OBR.4']['OBR.4.2']
);

var observationDateTime = hl7Value(
    msg['OBR']['OBR.7']['OBR.7.1']
);

var reportStatus = mapResultStatus(
    hl7Value(msg['OBR']['OBR.25']['OBR.25.1'])
);

var patientFullUrl =
    'urn:uuid:' + UUIDGenerator.getUUID();

var serviceRequestFullUrl =
    'urn:uuid:' + UUIDGenerator.getUUID();

var diagnosticReportFullUrl =
    'urn:uuid:' + UUIDGenerator.getUUID();

var patientIdentifierSystem =
    'https://integration-lab.example.org/' +
    'fhir/identifier/patient';

var orderIdentifierSystem =
    'https://integration-lab.example.org/' +
    'fhir/identifier/order';

var accessionIdentifierSystem =
    'https://integration-lab.example.org/' +
    'fhir/identifier/accession';

var observationIdentifierSystem =
    'https://integration-lab.example.org/' +
    'fhir/identifier/observation';

var patient = {
    resourceType: 'Patient',
    identifier: [
        {
            system: patientIdentifierSystem,
            value: patientId
        }
    ],
    name: [
        {
            family: lastName,
            given: [firstName]
        }
    ],
    gender: mapGender(sex)
};

if (birthDate) {
    patient.birthDate = fhirDate(birthDate);
}

var serviceRequest = {
    resourceType: 'ServiceRequest',
    identifier: [
        {
            system: orderIdentifierSystem,
            value: orderId
        }
    ],
    status: 'completed',
    intent: 'order',
    code: {
        coding: [
            {
                system: 'http://loinc.org',
                code: panelCode,
                display: panelDescription
            }
        ],
        text: panelDescription
    },
    subject: {
        reference: patientFullUrl
    }
};

var diagnosticReport = {
    resourceType: 'DiagnosticReport',
    identifier: [
        {
            system: accessionIdentifierSystem,
            value: accessionId
        }
    ],
    status: reportStatus,
    code: {
        coding: [
            {
                system: 'http://loinc.org',
                code: panelCode,
                display: panelDescription
            }
        ],
        text: panelDescription
    },
    subject: {
        reference: patientFullUrl
    },
    basedOn: [
        {
            reference: serviceRequestFullUrl
        }
    ],
    result: []
};

if (observationDateTime) {
    diagnosticReport.effectiveDateTime =
        fhirDateTime(observationDateTime);
}

var bundle = {
    resourceType: 'Bundle',
    type: 'transaction',
    identifier: {
        system:
            'https://integration-lab.example.org/' +
            'fhir/identifier/message',
        value: controlId
    },
    entry: []
};

bundle.entry.push({
    fullUrl: patientFullUrl,
    resource: patient,
    request: {
        method: 'PUT',
        url:
            'Patient?identifier=' +
            patientIdentifierSystem + '%7C' +
            encodeURIComponent(patientId)
    }
});

bundle.entry.push({
    fullUrl: serviceRequestFullUrl,
    resource: serviceRequest,
    request: {
        method: 'PUT',
        url:
            'ServiceRequest?identifier=' +
            orderIdentifierSystem + '%7C' +
            encodeURIComponent(orderId)
    }
});

var obxCount = msg['OBX'].length();

if (obxCount === 0) {
    throw new Error(
        'ORU message contains no OBX segments'
    );
}

for (var i = 0; i < obxCount; i++) {
    var obx = msg['OBX'][i];

    var setId = hl7Value(
        obx['OBX.1']['OBX.1.1']
    );

    var valueType = hl7Value(
        obx['OBX.2']['OBX.2.1']
    );

    var observationCode = required(
        hl7Value(obx['OBX.3']['OBX.3.1']),
        'OBX-3.1'
    );

    var observationDescription = hl7Value(
        obx['OBX.3']['OBX.3.2']
    );

    var observationValue = required(
        hl7Value(obx['OBX.5']['OBX.5.1']),
        'OBX-5.1'
    );

    var units = hl7Value(
        obx['OBX.6']['OBX.6.1']
    );

    var referenceRange = hl7Value(
        obx['OBX.7']['OBX.7.1']
    );

    var abnormalFlag = hl7Value(
        obx['OBX.8']['OBX.8.1']
    );

    var observationStatus = mapResultStatus(
        hl7Value(obx['OBX.11']['OBX.11.1'])
    );

    var observationFullUrl =
        'urn:uuid:' + UUIDGenerator.getUUID();

    var observationIdentifier =
        controlId + '-' + setId;

    var observation = {
        resourceType: 'Observation',
        identifier: [
            {
                system: observationIdentifierSystem,
                value: observationIdentifier
            }
        ],
        status: observationStatus,
        category: [
            {
                coding: [
                    {
                        system:
                            'http://terminology.hl7.org/' +
                            'CodeSystem/' +
                            'observation-category',
                        code: 'laboratory',
                        display: 'Laboratory'
                    }
                ]
            }
        ],
        code: {
            coding: [
                {
                    system: 'http://loinc.org',
                    code: observationCode,
                    display: observationDescription
                }
            ],
            text: observationDescription
        },
        subject: {
            reference: patientFullUrl
        },
        basedOn: [
            {
                reference: serviceRequestFullUrl
            }
        ]
    };

    if (observationDateTime) {
        observation.effectiveDateTime =
            fhirDateTime(observationDateTime);
    }

    if (valueType === 'NM') {
        observation.valueQuantity = {
            value: Number(observationValue),
            unit: units,
            system: 'http://unitsofmeasure.org',
            code: units
        };
    } else {
        observation.valueString = observationValue;
    }

    if (referenceRange) {
        observation.referenceRange = [
            {
                text: referenceRange
            }
        ];
    }

    if (abnormalFlag) {
        observation.interpretation = [
            {
                coding: [
                    {
                        system:
                            'http://terminology.hl7.org/' +
                            'CodeSystem/' +
                            'v3-ObservationInterpretation',
                        code: abnormalFlag
                    }
                ]
            }
        ];
    }

    diagnosticReport.result.push({
        reference: observationFullUrl
    });

    bundle.entry.push({
        fullUrl: observationFullUrl,
        resource: observation,
        request: {
            method: 'PUT',
            url:
                'Observation?identifier=' +
                observationIdentifierSystem + '%7C' +
                encodeURIComponent(
                    observationIdentifier
                )
        }
    });
}

bundle.entry.push({
    fullUrl: diagnosticReportFullUrl,
    resource: diagnosticReport,
    request: {
        method: 'PUT',
        url:
            'DiagnosticReport?identifier=' +
            accessionIdentifierSystem + '%7C' +
            encodeURIComponent(accessionId)
    }
});

var fhirBundle = JSON.stringify(bundle, null, 2);

channelMap.put('fhirBundle', fhirBundle);
channelMap.put('fhirControlId', controlId);
channelMap.put('fhirPatientId', patientId);
channelMap.put('fhirOrderId', orderId);
channelMap.put('fhirAccessionId', accessionId);
channelMap.put('fhirObservationCount', obxCount);
channelMap.put(
    'fhirBundleEntryCount',
    bundle.entry.length
);

var environment = String(
    $cfg('ENVIRONMENT')
);

channelMap.put(
    'environment',
    environment
);

logger.info(
    '[CH05 FHIR] environment=' + environment +
    ', mirthMessageId=' +
    connectorMessage.getMessageId() +
    ', observations=' + obxCount +
    ', bundleEntries=' + bundle.entry.length
);

channel.postprocessingScript:
// This script executes once after a message has been processed
// Responses returned from here will be stored as "Postprocessor" in the response map
return;

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;
